input.content:
@import "tailwindcss";

:root {
  /* light theme */
  --ink: #0d1f33;
  --ink-dim: rgba(13, 31, 51, 0.62);
  --dark: #0d1f33;
  --accent: #2f9e5f;

  /* liquid glass tokens (light) */
  --glass-bg: rgba(255, 255, 255, 0.55);
  --glass-bg-strong: rgba(255, 255, 255, 0.75);
  --glass-border: rgba(13, 31, 51, 0.1);
}

* {
  box-sizing: border-box;
}

html {
  background: #ffffff;
}
body {
  margin: 0;
  padding: 0;
  color: var(--ink);
  font-family: var(--font-sans), system-ui, sans-serif;
  background: transparent;
  overflow-x: hidden;
}

/* ------------------------------------------------------------------ */
/* Background (halftone koi image)                                     */
/* ------------------------------------------------------------------ */
.bg-image {
  position: fixed;
  inset: 0;
  z-index: -2;
  background: #ffffff url("/bg.jpg") no-repeat right 1vw center;
  background-size: min(54vw, 760px) auto;
}

.bg-tint {
  position: fixed;
  inset: 0;
  z-index: -1;
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.9) 0%,
    rgba(255, 255, 255, 0.4) 38%,
    rgba(255, 255, 255, 0) 58%
  );
  pointer-events: none;
}

/* ------------------------------------------------------------------ */
/* Liquid glass primitive (light)                                     */
/* ------------------------------------------------------------------ */
.glass {
  position: relative;
  background: var(--glass-bg);
  backdrop-filter: blur(6px) saturate(150%) url(#liquid-glass);
  -webkit-backdrop-filter: blur(14px) saturate(160%);
  border: 1px solid var(--glass-border);
  box-shadow:
    0 14px 34px rgba(13, 31, 51, 0.14),
    inset 0 1px 1px rgba(255, 255, 255, 0.7);
}

@supports not (backdrop-filter: url(#liquid-glass)) {
  .glass {
    backdrop-filter: blur(16px) saturate(160%);
  }
}

.glass::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.6) 0%,
    rgba(255, 255, 255, 0.05) 45%,
    rgba(255, 255, 255, 0) 100%
  );
  pointer-events: none;
}

/* ------------------------------------------------------------------ */
/* Nav                                                                */
/* ------------------------------------------------------------------ */
.nav {
  position: fixed;
  top: 22px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 50;
  display: inline-flex;
  align-items: center;
  gap: 26px;
  padding: 8px 8px 8px 20px;
  border-radius: 999px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
}
.nav-logo svg {
  display: block;
}
.nav-wordmark {
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -0.02em;
  color: var(--ink);
}

.nav-links {
  display: flex;
  gap: 26px;
  font-size: 14px;
  font-weight: 500;
}
.nav-links a {
  color: var(--ink-dim);
  text-decoration: none;
  cursor: pointer;
  transition: color 0.2s ease;
}
.nav-links a:hover {
  color: var(--ink);
}

.pill-contact {
  background: var(--dark);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 10px 22px;
  font-family: var(--font-sans);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.2s ease;
  box-shadow: 0 6px 18px rgba(13, 31, 51, 0.22);
}
.pill-contact:hover {
  transform: translateY(-1px);
}

@media (max-width: 720px) {
  .nav-links {
    display: none;
  }
}

/* ------------------------------------------------------------------ */
/* Pills & buttons                                                    */
/* ------------------------------------------------------------------ */
.pill {
  border-radius: 999px;
  padding: 9px 18px;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  cursor: pointer;
  transition: transform 0.15s ease, background 0.2s ease;
}
.pill:hover {
  transform: translateY(-1px);
  background: var(--glass-bg-strong);
}

.label-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 15px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--ink-dim);
  cursor: default;
}
.label-pill.center {
  justify-content: center;
}
.label-pill .diamond {
  color: var(--accent);
  font-size: 10px;
}
.dot {
