// Per-library mining spec.
// The STEP STRUCTURE is authored; the EVIDENCE (frequencies, receipts, which
// co-deps actually appear) is mined from real repos by engine/mine.mjs.
//
// A step is either:
//   kind: "packages" — presence of npm packages in repos' package.json
//   kind: "pattern"  — call-site patterns found in source (ripgrep today,
//                      entire-graph `neighbors`/`impact` when available)

export const LIBRARIES = {
  tiptap: {
    id: "tiptap-collab-editor",
    library: "tiptap",
    title: "A collaborative rich-text",
    emphasis: "editor",
    runnersUp: "Lexical, Slate, ProseMirror",
    keywords: [
      "editor", "rich text", "rich-text", "collaborative", "collab",
      "google docs", "docs", "wysiwyg", "tiptap", "prosemirror",
      "comments", "writing",
    ],
    repos: [
      "https://github.com/steven-tey/novel",
      "https://github.com/yjs/yjs-demos",
      "https://github.com/sereneinserenade/tiptap-comment-extension",
    ],
    steps: [
      {
        name: "Install",
        kind: "packages",
        packages: [
          "@tiptap/react", "@tiptap/core", "@tiptap/starter-kit",
          "@tiptap/extension-collaboration", "yjs", "y-websocket",
          "@hocuspocus/provider",
        ],
        note: "Core packages the mined repos install together.",
      },
      {
        name: "Core editor setup",
        kind: "pattern",
        patterns: ["useEditor\\(", "new Editor\\("],
        code: "const editor = useEditor({\n  extensions: [StarterKit, /* … */],\n})",
        note: "The dominant wiring: useEditor / new Editor with StarterKit + extensions.",
      },
      {
        name: "Realtime collaboration provider",
        kind: "pattern",
        patterns: ["new WebsocketProvider\\(", "HocuspocusProvider", "new Y\\.Doc\\("],
        code: "const ydoc = new Y.Doc()\nnew WebsocketProvider(WS_URL, room, ydoc)",
        note: "Realtime layer paired with the editor (Yjs doc + a websocket provider).",
      },
      {
        name: "Inline comments",
        kind: "pattern",
        patterns: ["Mark\\.create\\(", "addAttributes", "name:\\s*['\"]comment['\"]"],
        code: "Mark.create({ name: 'comment', /* addAttributes… */ })",
        note: "Less standardized — repos hand-roll a custom Mark for comments.",
      },
    ],
  },
};

export function libKeys() {
  return Object.keys(LIBRARIES);
}

