// Per-library mining spec.
// STEP STRUCTURE is authored; EVIDENCE (frequencies + file:line receipts) is
// mined from real repos by engine/mine.mjs using `entire graph edges`.
//
// Step kinds:
//   kind: "imports" — count IMPORTS edges to external modules in `modules`
//   kind: "calls"   — count CALLS/CONSTRUCTS edges whose called/constructed
//                     name is in `symbols`

export const LIBRARIES = {
  tiptap: {
    id: "tiptap-collab-editor",
    library: "tiptap",
    title: "A collaborative rich-text",
    emphasis: "editor",
    runnersUp: "Lexical, Slate, ProseMirror",
    keywords: [
      "editor", "rich text", "rich-text", "collaborative", "collab",
      "google docs", "docs", "wysiwyg", "tiptap", "prosemirror",
      "comments", "writing",
    ],
    // real repos that use tiptap (shallow-cloned by the engine)
    repos: [
      "https://github.com/steven-tey/novel",
      "https://github.com/yjs/yjs-demos",
      "https://github.com/sereneinserenade/tiptap-comment-extension",
    ],
    steps: [
      {
        name: "Install",
        kind: "imports",
        modules: [
          "@tiptap/react", "@tiptap/core", "@tiptap/starter-kit",
          "@tiptap/extension-collaboration", "@tiptap/pm",
          "yjs", "y-websocket", "y-prosemirror", "@hocuspocus/provider",
        ],
        note: "Packages the mined repos actually import together (not just declare).",
      },
      {
        name: "Core editor setup",
        kind: "calls",
        symbols: ["useEditor", "Editor"],
        code: "const editor = useEditor({\n  extensions: [StarterKit, /* … */],\n})",
        note: "The dominant wiring: useEditor / new Editor with StarterKit + extensions.",
      },
      {
        name: "Realtime collaboration provider",
        kind: "calls",
        symbols: ["WebsocketProvider", "HocuspocusProvider", "Doc"],
        code: "const ydoc = new Y.Doc()\nnew WebsocketProvider(WS_URL, room, ydoc)",
        note: "Realtime layer paired with the editor: a Yjs doc + a websocket provider.",
      },
      {
        name: "Inline comments",
        kind: "calls",
        symbols: ["Mark", "addAttributes"],
        code: "Mark.create({ name: 'comment', /* addAttributes… */ })",
        note: "Less standardized — repos hand-roll a custom Mark for comments.",
      },
    ],
  },
};

// Thin adapter over the `entire graph` CLI (entire-graph plugin).
// This is the ONLY place that shells out to entire-graph — swap the impl here
// if the CLI surface changes.
import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";

const ENTIRE =
  process.env.ENTIRE_BIN ||
  [`${process.env.HOME}/.local/bin/entire`, "/usr/local/bin/entire", "entire"].find(
    (p) => p === "entire" || existsSync(p)
  );

export function graphAvailable() {
  try {
    execFileSync(ENTIRE, ["graph", "capabilities", "--json"], {
      stdio: ["ignore", "ignore", "ignore"],
    });
    return true;
  } catch {
    return false;
  }
}

// Stream relation records of the given types for a repo. Returns parsed
// { record_type:"relation", from_id, to_id, type, evidence:[{file_path,start_line,detail}] }
export function edges(repoPath, relations, { worktree = false } = {}) {
  const args = [
    "graph", "edges",
    "--repo", repoPath,
    "--relation", relations.join(","),
    "--format", "ndjson",
  ];
  if (worktree) args.push("--worktree");

  let out = "";
  try {
    out = execFileSync(ENTIRE, args, {
      maxBuffer: 1024 * 1024 * 1024,
      encoding: "utf8",
    });
  } catch (e) {
    out = e.stdout ? e.stdout.toString() : "";
  }

  const recs = [];
  for (const line of out.split("\n")) {
    if (!line || line[0] !== "{") continue;
    let obj;
    try {
      obj = JSON.parse(line);
    } catch {
      continue;
    }
    if (obj.record_type === "relation") recs.push(obj);
  }
  return recs;
}

// module name from an IMPORTS edge, e.g. "external:import:@tiptap/react" -> "@tiptap/react"
export function importedModule(rec) {
  if (typeof rec.to_id === "string" && rec.to_id.startsWith("external:import:")) {
    return rec.to_id.slice("external:import:".length);
  }
  const ev = rec.evidence && rec.evidence[0];
  return ev && ev.detail ? ev.detail : null;
}

// Recipe mining engine — powered by entire-graph.
//
//   node engine/mine.mjs [library]      (default: tiptap)
//
// For each real repo that uses the library it:
//   1. shallow-clones it into engine/.cache
//   2. runs `entire graph edges` (IMPORTS / CALLS / CONSTRUCTS)
//   3. filters edges to the library's modules + API symbols
//   4. aggregates frequencies + real file:line receipts across repos
//   5. writes lib/recipes.generated.json for the app to serve.
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { LIBRARIES } from "./libraries.mjs";
import { edges, importedModule, graphAvailable } from "./graph.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const CACHE = join(__dirname, ".cache");
const OUT = join(ROOT, "lib", "recipes.generated.json");

const repoName = (url) => url.replace(/\.git$/, "").split("/").pop();
const lastSeg = (name) => (name ? name.split(".").pop() : name);

function clone(url) {
  const dest = join(CACHE, repoName(url));
  if (existsSync(join(dest, ".git"))) return dest;
  mkdirSync(CACHE, { recursive: true });
  console.log(`  cloning ${url} …`);
  execFileSync(
    "git",
    ["clone", "--depth", "1", "--single-branch", url, dest],
    { stdio: ["ignore", "ignore", "inherit"], timeout: 180000 }
  );
  return dest;
}

function receipt(repo, url, file, line) {
  const label = `${repo}/${file}${line ? `:${line}` : ""}`;
  const href = `${url}/blob/HEAD/${file}${line ? `#L${line}` : ""}`;
  return { label, url: href };
}

function moduleMatches(mod, modules) {
  return modules.some((m) => mod === m || mod.startsWith(m + "/"));
}

function mine(libKey) {
  const spec = LIBRARIES[libKey];
  if (!spec) throw new Error(`unknown library: ${libKey}`);

  const repos = spec.repos.map((url) => {
    try {
      return { url, path: clone(url), name: repoName(url) };
    } catch (e) {
      console.warn(`  ! skip ${url}: ${e.message.split("\n")[0]}`);
      return null;
    }
  }).filter(Boolean);

  // pull edges once per repo
  for (const r of repos) {
    console.log(`  graphing ${r.name} …`);
    r.imports = edges(r.path, ["IMPORTS"]);
    r.calls = edges(r.path, ["CALLS", "CONSTRUCTS"]);
  }

  const total = repos.length;
  let callSites = 0;

  const steps = spec.steps.map((step) => {
    const hitRepos = new Set();
    const receipts = [];
    const seen = new Set();

    if (step.kind === "imports") {
      const perModule = new Map(); // module -> Set(repo)
      for (const r of repos) {
        for (const rec of r.imports) {
          const mod = importedModule(rec);
          if (!mod || !moduleMatches(mod, step.modules)) continue;
          hitRepos.add(r.name);
          if (!perModule.has(mod)) perModule.set(mod, new Set());
          perModule.get(mod).add(r.name);
          const ev = rec.evidence && rec.evidence[0];
          const key = `${r.name}:${ev?.file_path}:${mod}`;
          if (ev?.file_path && !seen.has(key) && receipts.length < 4) {
            seen.add(key);
            receipts.push(receipt(r.name, r.url, ev.file_path, ev.start_line));
          }
        }
      }
      const ranked = [...perModule.entries()]
        .sort((a, b) => b[1].size - a[1].size)
        .map(([m, s]) => ({ m, n: s.size }));
      callSites += ranked.reduce((a, x) => a + x.n, 0);
      const installLine = ranked.filter((x) => x.n >= 1).map((x) => x.m).join(" ");
      return {
        name: step.name,
        freq: `${hitRepos.size}/${total}`,
        level: hitRepos.size >= Math.ceil(total / 2) ? "high" : "warn",
        code: installLine ? `npm i ${installLine}` : step.code,
        note:
          step.note +
          (ranked.length
            ? `  Most common: ${ranked.slice(0, 3).map((x) => `${x.m} (${x.n}/${total})`).join(", ")}.`
            : ""),
        receipts,
      };
    }

    // kind: "calls"
    for (const r of repos) {
      for (const rec of r.calls) {
        const ev = rec.evidence && rec.evidence[0];
        const called = ev?.detail || lastSeg(rec.to_id?.split(":").pop());
        const name = lastSeg(called);
        if (!name || !step.symbols.includes(name)) continue;
        hitRepos.add(r.name);
        const key = `${r.name}:${ev?.file_path}:${ev?.start_line}`;
        if (ev?.file_path && !seen.has(key)) {
          seen.add(key);
          callSites += 1;
          if (receipts.length < 5)
            receipts.push(receipt(r.name, r.url, ev.file_path, ev.start_line));
        }
      }
    }
