// Load the mined corpus (lib/recipes.generated.json) into the Delta table
// workspace.recipe.recipes via the Databricks SQL Statement Execution API.
//
//   node engine/load-databricks.mjs
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");

// minimal .env.local loader
for (const line of (() => {
  try {
    return readFileSync(join(ROOT, ".env.local"), "utf8").split("\n");
  } catch {
    return [];
  }
})()) {
  const m = line.match(/^([A-Z_]+)=(.*)$/);
  if (m) process.env[m[1]] = m[2];
}

const { DATABRICKS_HOST, DATABRICKS_TOKEN, DATABRICKS_WAREHOUSE_ID } = process.env;
const CATALOG = process.env.DATABRICKS_CATALOG || "workspace";
const SCHEMA = process.env.DATABRICKS_SCHEMA || "recipe";
const TABLE = `${CATALOG}.${SCHEMA}.recipes`;

async function exec(statement) {
  const res = await fetch(`${DATABRICKS_HOST}/api/2.0/sql/statements`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${DATABRICKS_TOKEN}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      warehouse_id: DATABRICKS_WAREHOUSE_ID,
      statement,
      wait_timeout: "50s",
    }),
  });
  const json = await res.json();
  if (json.status?.state !== "SUCCEEDED") {
    throw new Error(json.status?.error?.message || JSON.stringify(json.status));
  }
  return json;
}

const q = (s) => `'${String(s ?? "").replace(/'/g, "''")}'`;
const arr = (a) => `array(${(a || []).map(q).join(", ")})`;

const recipes = JSON.parse(readFileSync(join(ROOT, "lib", "recipes.generated.json"), "utf8"));
console.log(`loading ${recipes.length} recipe(s) into ${TABLE} …`);

for (const r of recipes) {
  await exec(`DELETE FROM ${TABLE} WHERE id = ${q(r.id)}`);
  await exec(
    `INSERT INTO ${TABLE} VALUES (${q(r.id)}, ${q(r.library)}, ${q(r.title)}, ` +
      `${q(r.emphasis || "")}, ${r.reposMined || 0}, ${r.callSites || 0}, ${q(r.runnersUp || "")}, ` +
      `${arr(r.keywords)}, ${q(JSON.stringify(r.steps || []))}, ${arr(r.sources)}, 'mined', current_timestamp())`
  );
  console.log(`  ✓ ${r.id}`);
}

const count = await exec(`SELECT count(*) FROM ${TABLE}`);
console.log(`done. rows in table: ${count.result?.data_array?.[0]?.[0]}`);

// Databricks-backed recipe corpus — the lakehouse serving layer.
// Reads/writes workspace.recipe.recipes via the SQL Statement Execution API.
// If the DATABRICKS_* env vars are absent, corpusEnabled() is false and the
// API route falls back to the local JSON corpus.
import type { Recipe } from "./recipes";

const HOST = process.env.DATABRICKS_HOST;
const TOKEN = process.env.DATABRICKS_TOKEN;
const WAREHOUSE = process.env.DATABRICKS_WAREHOUSE_ID;
const CATALOG = process.env.DATABRICKS_CATALOG || "workspace";
const SCHEMA = process.env.DATABRICKS_SCHEMA || "recipe";
const TABLE = `${CATALOG}.${SCHEMA}.recipes`;

export function corpusEnabled(): boolean {
  return Boolean(HOST && TOKEN && WAREHOUSE);
}

async function exec(statement: string) {
  const res = await fetch(`${HOST}/api/2.0/sql/statements`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      warehouse_id: WAREHOUSE,
      statement,
      wait_timeout: "30s",
    }),
  });
  const json = await res.json();
  if (json.status?.state !== "SUCCEEDED") {
    throw new Error(json.status?.error?.message || "databricks query failed");
  }
  return json;
}

const q = (s: string) => `'${String(s ?? "").replace(/'/g, "''")}'`;
const arr = (a: string[]) => `array(${(a || []).map(q).join(", ")})`;
const asArray = (v: unknown): string[] => {
  try {
    return Array.isArray(v) ? (v as string[]) : JSON.parse(v as string);
  } catch {
    return [];
  }
};
const asJson = (v: unknown) => {
  try {
    return typeof v === "string" ? JSON.parse(v) : v;
  } catch {
    return [];
  }
};

function rowToRecipe(row: string[]): Recipe {
  const [id, library, title, emphasis, repos, calls, runnersUp, keywords, steps, sources] = row;
  return {
    id,
    library,
    title,
    emphasis: emphasis || "",
    reposMined: Number(repos) || 0,
    callSites: Number(calls) || 0,
    runnersUp: runnersUp || "",
    keywords: asArray(keywords),
    steps: asJson(steps),
    sources: asArray(sources),
  } as Recipe;
}

export async function getAllRecipes(): Promise<Recipe[]> {
  const r = await exec(
    `SELECT id, library, title, emphasis, repos_mined, call_sites, runners_up, keywords, steps, sources FROM ${TABLE}`
  );
  return (r.result?.data_array || []).map(rowToRecipe);
}

// same keyword scoring as the local findRecipe, over the lakehouse rows
export async function queryRecipe(query: string): Promise<Recipe | null> {
  const qq = query.toLowerCase().trim();
  if (!qq) return null;
  let best: Recipe | null = null;
  let score = 0;
  for (const r of await getAllRecipes()) {
    let s = 0;
    for (const kw of r.keywords || []) if (qq.includes(kw)) s += kw.length;
    if (s > score) {
      score = s;
      best = r;
    }
  }
  return best;
}

// write-back: upsert a freshly-generated recipe into the lakehouse
export async function saveRecipe(r: Recipe & { sources?: string[] }): Promise<void> {
  await exec(`DELETE FROM ${TABLE} WHERE id = ${q(r.id)}`);
  await exec(
    `INSERT INTO ${TABLE} VALUES (${q(r.id)}, ${q(r.library)}, ${q(r.title)}, ` +
      `${q(r.emphasis || "")}, ${r.reposMined || 0}, ${r.callSites || 0}, ${q(r.runnersUp || "")}, ` +
      `${arr(r.keywords)}, ${q(JSON.stringify(r.steps || []))}, ${arr(r.sources || [])}, 'live', current_timestamp())`
  );
}

import { spawnSync } from "node:child_process";
import { findRecipe } from "@/lib/recipes";
import { corpusEnabled, queryRecipe, saveRecipe } from "@/lib/corpus";

export const dynamic = "force-dynamic";
export const maxDuration = 300;

// Public query endpoint, served from the Databricks lakehouse when configured.
//   GET /api/recipe?q=collaborative+editor           read: databricks → local corpus
//   GET /api/recipe?q=...&live=1                      miss: mine on-demand + write back
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const q = searchParams.get("q") ?? "";
  const live = searchParams.get("live") === "1";

  if (!q.trim()) {
    return Response.json(
      { error: "missing query", usage: "/api/recipe?q=collaborative+editor" },
      { status: 400 }
    );
  }

  // 1. Databricks lakehouse (the live serving store)
  if (corpusEnabled()) {
    try {
      const hit = await queryRecipe(q);
      if (hit) return Response.json({ ...hit, source: "databricks" });
    } catch {
      // fall through to local corpus if the warehouse is unreachable
    }
  }

  // 2. local corpus (mined + hand-authored) — always available
  const local = findRecipe(q);
  if (local) return Response.json({ ...local, source: "corpus" });

  // 3. no hit — mine on demand?
  if (!live) {
    return Response.json(
      { error: "not in corpus", query: q, hint: "retry with &live=1 to mine it on-demand" },
      { status: 404 }
    );
  }

  // 4. live: entire-graph engine discovers → mines → derives
  const res = spawnSync("node", ["engine/cli.mjs", "generate", q, "--json"], {
    cwd: process.cwd(),
    encoding: "utf8",
    timeout: 240000,
    maxBuffer: 64 * 1024 * 1024,
    env: { ...process.env, PATH: `${process.env.HOME}/.local/bin:${process.env.PATH}` },
  });

  if (res.status !== 0 || !res.stdout?.trim()) {
    return Response.json(
      { error: "generation failed", query: q, detail: (res.stderr || "").split("\n").slice(-3).join("\n") },
      { status: 502 }
    );
  }

  try {
    const recipe = JSON.parse(res.stdout);
    // write the new recipe back into the lakehouse so the corpus grows
    let source = "live";
    if (corpusEnabled()) {
      try {
        await saveRecipe(recipe);
        source = "live+databricks";
      } catch {
        /* keep source=live if write-back fails */
      }
    }
    return Response.json({ ...recipe, source });
  } catch {
    return Response.json({ error: "could not parse engine output", query: q }, { status: 502 });
  }
}

